:- pred high_risk_ai_system/1, gloss('AI system classified as high-risk under the regulation'), source('celex:32024R1689/oj#art_19').
:- pred financial_institution/1, gloss('provider subject to Union financial services law governance requirements'), source('celex:32024R1689/oj#art_19').
:- pred logs_under_control/2, gloss('logs automatically generated by a system that are under the control of a provider'), source('celex:32024R1689/oj#art_19').
:- pred appropriate_retention_period/2, gloss('period appropriate to intended purpose and at least six months unless otherwise provided'), source('celex:32024R1689/oj#art_19').

must_keep_logs(Provider, System) :-
    provider(Provider),
    high_risk_ai_system(System),
    logs_under_control(Provider, System),
    \+ financial_institution(Provider),
    appropriate_retention_period(System, _Period).

must_maintain_logs_as_financial_documentation(Provider, System) :-
    provider(Provider),
    high_risk_ai_system(System),
    financial_institution(Provider),
    logs_under_control(Provider, System).

appropriate_retention_period(System, months(6)) :-
    high_risk_ai_system(System),
    intended_purpose(System).

provenance(must_keep_logs/2, 'celex:32024R1689/oj#art_19').
provenance(must_maintain_logs_as_financial_documentation/2, 'celex:32024R1689/oj#art_19').
provenance(appropriate_retention_period/2, 'celex:32024R1689/oj#art_19').

